#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <errno.h>
#include <sys/vm86.h>
#include <string.h>

/* 
 * NOTE: The definition of struct vm86_struct is highly architecture-dependent 
 * and complex. This example uses a simplified, representative structure 
 * based on typical Linux kernel headers to demonstrate the syscall usage pattern.
 */
struct vm86_struct {
    long regs[18]; // Placeholder for registers EAX, EBX, ESI, EDI, etc.
    unsigned long flags;
    unsigned short es, cs, ss, ds, fs, gs; 
    // Additional fields for interrupt handling and state...
};

// Index placeholder for EAX register
#define V86_EAX 0 

int main() {
    // Check for architecture support (vm86 is i386-specific)
    #ifndef __i386__
        fprintf(stderr, "Error: vm86old is primarily supported on 32-bit Intel systems.\n");
        return EXIT_FAILURE;
    #endif

    struct vm86_struct info;
    memset(&info, 0, sizeof(info));

    // 1. Setup the initial 8086 state. 
    // In a real emulator, CS:IP would point to a loaded BIOS or DOS entry point.
    info.cs = 0x7000; 
    info.regs[V86_EAX] = 0x100; // Set up a dummy register value
    info.flags = 0; 

    printf("Initializing VM86 structure and calling vm86old()...\n");

    // Call vm86old. This typically blocks until an event causes an exit.
    if (vm86old(&info) == -1) {
        if (errno == ENOSYS) {
            fprintf(stderr, "Error: vm86old is not implemented on this kernel configuration.\n");
        } else if (errno == EFAULT) {
            fprintf(stderr, "Error: Invalid pointer passed (EFAULT).\n");
        } else {
            perror("vm86old failed unexpectedly");
        }
        return EXIT_FAILURE;
    }

    printf("Successfully exited VM86 mode. Final EAX: %ld\n", info.regs[V86_EAX]);

    return EXIT_SUCCESS;
}
